using System;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;
public class FinalizeUI084 {public static string Main(){var root=GameObject.Find("Castle_Services_Prototype").transform;var h=root.Find("03_Service_Houses/04_Professions");foreach(var t in root.GetComponentsInChildren<Text>(true).Where(t=>t.name=="Localized_Text")){t.GetComponentInParent<CanvasScaler>(true).dynamicPixelsPerUnit=1;t.resizeTextMaxSize=300;}foreach(Transform t in h.Find("24_Armory_Wall_Decor")){if(t.name.StartsWith("Left")||t.name.StartsWith("Right")){var p=t.localPosition;p.z=2.9f;t.localPosition=p;}}Canvas.ForceUpdateCanvases();EditorSceneManager.MarkSceneDirty(h.gameObject.scene);EditorSceneManager.SaveScene(h.gameObject.scene);return "UI density fixed; shields moved off windows.";}}

